window.LESSON_DATA = {"schemaVersion":"2.0.0","version":"2.0.0","buildDate":"2026-08-01","course":"IB Mathematics: Applications and Interpretation SL","unit":{"number":2,"title":"Functions"},"lesson":{"number":"2.5","slug":"transformations-composition-inverses","title":"Transformations, Composition, and Inverses","subtitle":"Track how parameters move, stretch and reflect graphs, then connect reversible processes through inverse functions.","syllabus_focus":"Graph transformations and inverse functions, with composition presented as a clearly labelled extension where appropriate.","skill_keys":["IBAI.U2.TRANSFORM"],"objectives":["Describe and construct translations, reflections and stretches of familiar graphs.","Apply more than one transformation in the correct order.","Find and interpret inverse functions and domain restrictions.","Use composition to represent multi-stage processes and verify inverse relationships."],"vocab":["translation","reflection","vertical stretch","horizontal stretch","transformation","inverse function","one-to-one","restriction","composition","identity"],"technology":"Use overlays and tables to compare a base graph with its transform; verify inverse graphs by reflection in y=x and by composing rules.","inquiry":"A temperature conversion, a currency conversion and a sensor calibration are all reversible processes. What conditions make reversal possible, and how do graph transformations reveal the structure?"},"slides":[{"section":"Launch","title":"Transformations, Composition, and Inverses","html":"<div class=\"cover-grid\"><div><div class=\"cover-kicker\">IB Mathematics: Applications and Interpretation SL</div><div class=\"cover-number\">2.5</div><h1>Transformations, Composition, and Inverses</h1><p class=\"cover-subtitle\">Track how parameters move, stretch and reflect graphs, then connect reversible processes through inverse functions.</p><div class=\"pill-row\"><span>Inquiry</span><span>Technology</span><span>Modelling</span><span>Interpretation</span><span>Evaluation</span></div><button class=\"primary-btn route-jump\" data-go=\"practice\">Open Practice Studio</button></div><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"transformations and inverses\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M80 190 Q190 35 300 190 M300 190 Q390 60 475 190\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"55\" y1=\"220\" x2=\"470\" y2=\"35\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">transformations and inverses</text>\n    </svg></div></div>","kind":"cover","eyebrow":"Unit 2 · Functions"},{"section":"Launch","title":"Inquiry launch","html":"<div class=\"launch-panel\"><h2>Start with a decision</h2><p>A temperature conversion, a currency conversion and a sensor calibration are all reversible processes. What conditions make reversal possible, and how do graph transformations reveal the structure?</p><textarea class=\"student-note\" data-note=\"inquiry\" placeholder=\"Write an initial model, assumption or question before continuing.\"></textarea></div>","kind":"content","eyebrow":"Think before calculating"},{"section":"Launch","title":"Learning outcomes","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"obj-2.5-0\"><span>Describe and construct translations, reflections and stretches of familiar graphs.</span></label><label><input type=checkbox data-reflect=\"obj-2.5-1\"><span>Apply more than one transformation in the correct order.</span></label><label><input type=checkbox data-reflect=\"obj-2.5-2\"><span>Find and interpret inverse functions and domain restrictions.</span></label><label><input type=checkbox data-reflect=\"obj-2.5-3\"><span>Use composition to represent multi-stage processes and verify inverse relationships.</span></label></div>","kind":"content","eyebrow":"By the end"},{"section":"Launch","title":"Diagnostic checkpoint","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Prior knowledge</h2><p>Coordinate axes, substitution, equation solving, percentage change and clear use of units.</p></article><article class=\"focus-card\"><h2>Quick self-check</h2><p>Can you distinguish an input restriction from a graphing-window choice? Can you explain what a parameter means in context?</p></article></div><textarea class=\"student-note\" data-note=\"diagnostic\" placeholder=\"Record one strength and one question.\"></textarea>","kind":"content","eyebrow":"Activate prior learning"},{"section":"Launch","title":"Vocabulary and notation","html":"<div class=\"vocab-grid\"><span class=vocab-chip>translation</span><span class=vocab-chip>reflection</span><span class=vocab-chip>vertical stretch</span><span class=vocab-chip>horizontal stretch</span><span class=vocab-chip>transformation</span><span class=vocab-chip>inverse function</span><span class=vocab-chip>one-to-one</span><span class=vocab-chip>restriction</span><span class=vocab-chip>composition</span><span class=vocab-chip>identity</span></div><div class=\"callout\"><b>Communication standard:</b> define every variable, include units, and distinguish an exact result from a rounded interpretation.</div>","kind":"content","eyebrow":"Language matters"},{"section":"Launch","title":"IB command terms","html":"<div class=\"command-grid\"><div><b>Calculate / Find</b><span>Show relevant stages and a defensible final value.</span></div><div><b>Determine</b><span>Obtain the only possible answer.</span></div><div><b>Interpret</b><span>Connect the mathematics to variables, units and context.</span></div><div><b>Explain / Justify</b><span>Give mathematical reasons, not only a conclusion.</span></div><div><b>Evaluate / Comment</b><span>Judge validity using evidence, assumptions and limitations.</span></div><div><b>Construct / Sketch</b><span>Communicate an accurate, labelled representation.</span></div></div>","kind":"content","eyebrow":"Answer the verb"},{"section":"Launch","title":"Technology contract","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Purpose</h2><p>Use overlays and tables to compare a base graph with its transform; verify inverse graphs by reflection in y=x and by composing rules.</p></article><article class=\"focus-card\"><h2>Evidence to record</h2><p>Window/domain, equation or list entered, relevant output, units, rounding and a sentence interpreting the result.</p></article></div>","kind":"content","eyebrow":"GDC is a reasoning tool"},{"section":"Launch","title":"Lesson pathway","html":"<div class=\"workflow\"><div><b>1</b><span>Learn concepts through representations.</span></div><div><b>2</b><span>Investigate with technology.</span></div><div><b>3</b><span>Practise across four levels.</span></div><div><b>4</b><span>Complete IB tasks and a timed quiz.</span></div><div><b>5</b><span>Review evidence and mark completion.</span></div></div>","kind":"content","eyebrow":"Learn · practise · master"},{"section":"Concept cycle 1","title":"Translations","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>Adding outside a function moves the graph vertically; replacing x by x−h moves it horizontally by h.</p></article><div class=\"formula-panel\">\\[y=f(x-h)+k\\]</div></div>","kind":"content","eyebrow":"1 of 8"},{"section":"Concept cycle 1","title":"Translations: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"transformations and inverses\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M80 190 Q190 35 300 190 M300 190 Q390 60 475 190\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"55\" y1=\"220\" x2=\"470\" y2=\"35\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">transformations and inverses</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for translations?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 1","title":"Worked example: Translations","html":"<div class=\"worked\"><h2>Describe the transformation from y=x² to y=(x−3)²−5.</h2><ol class=\"method\"><li>x−3 shifts the graph 3 units right.</li><li>−5 shifts it 5 units down.</li><li>The vertex moves from (0,0) to (3,−5).</li></ol><div class=\"formula-panel\">\\[y=f(x-h)+k\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 1","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Describe y=|x+4|+2 from y=|x|.</b></div><textarea class=\"student-note tall\" data-note=\"turn-1\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">Translate 4 units left and 2 units up.</div></details></div>","kind":"content","eyebrow":"Translations"},{"section":"Concept cycle 1","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“x+4 moves the graph right.”</p><h3>Repair</h3><p>Horizontal translations have the opposite sign inside the function.</p></div></div>","kind":"content","eyebrow":"Translations"},{"section":"Concept cycle 2","title":"Reflections","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>Multiplying the output by −1 reflects in the x-axis; replacing x by −x reflects in the y-axis.</p></article><div class=\"formula-panel\">\\[y=-f(x),\\quad y=f(-x)\\]</div></div>","kind":"content","eyebrow":"2 of 8"},{"section":"Concept cycle 2","title":"Reflections: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"transformations and inverses\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M80 190 Q190 35 300 190 M300 190 Q390 60 475 190\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"55\" y1=\"220\" x2=\"470\" y2=\"35\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">transformations and inverses</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for reflections?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 2","title":"Worked example: Reflections","html":"<div class=\"worked\"><h2>Describe y=−e^(−x) from y=e^x.</h2><ol class=\"method\"><li>f(−x) reflects in the y-axis.</li><li>The leading negative reflects in the x-axis.</li><li>The combined graph is −e^(−x).</li></ol><div class=\"formula-panel\">\\[y=-f(x),\\quad y=f(-x)\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 2","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Describe y=−(x+1)² from y=x².</b></div><textarea class=\"student-note tall\" data-note=\"turn-2\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">Translate 1 left, then reflect in the x-axis.</div></details></div>","kind":"content","eyebrow":"Reflections"},{"section":"Concept cycle 2","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“−f(x) and f(−x) are the same transformation.”</p><h3>Repair</h3><p>One changes outputs; the other changes inputs.</p></div></div>","kind":"content","eyebrow":"Reflections"},{"section":"Concept cycle 3","title":"Stretches and compressions","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>A factor outside scales y-values; a factor inside changes x-values by the reciprocal scale.</p></article><div class=\"formula-panel\">\\[y=af(bx)\\]</div></div>","kind":"content","eyebrow":"3 of 8"},{"section":"Concept cycle 3","title":"Stretches and compressions: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"transformations and inverses\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M80 190 Q190 35 300 190 M300 190 Q390 60 475 190\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"55\" y1=\"220\" x2=\"470\" y2=\"35\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">transformations and inverses</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for stretches and compressions?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 3","title":"Worked example: Stretches and compressions","html":"<div class=\"worked\"><h2>Describe y=3f(2x).</h2><ol class=\"method\"><li>3 gives a vertical stretch by factor 3.</li><li>2 inside gives a horizontal compression by factor 1/2.</li><li>Track coordinates: (x,y)→(x/2,3y).</li></ol><div class=\"formula-panel\">\\[y=af(bx)\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 3","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Describe y=0.5f(x/4).</b></div><textarea class=\"student-note tall\" data-note=\"turn-3\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">Vertical compression by 1/2 and horizontal stretch by factor 4.</div></details></div>","kind":"content","eyebrow":"Stretches and compressions"},{"section":"Concept cycle 3","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“f(3x) stretches horizontally by 3.”</p><h3>Repair</h3><p>Inside factors act reciprocally on x-coordinates.</p></div></div>","kind":"content","eyebrow":"Stretches and compressions"},{"section":"Concept cycle 4","title":"Order of combined transformations","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>For a formula, simplify the inside transformation carefully. The order matters when shifts and stretches act on the same coordinate.</p></article><div class=\"formula-panel\">\\[g(x)=2f(3(x-1))+4\\]</div></div>","kind":"content","eyebrow":"4 of 8"},{"section":"Concept cycle 4","title":"Order of combined transformations: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"transformations and inverses\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M80 190 Q190 35 300 190 M300 190 Q390 60 475 190\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"55\" y1=\"220\" x2=\"470\" y2=\"35\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">transformations and inverses</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for order of combined transformations?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 4","title":"Worked example: Order of combined transformations","html":"<div class=\"worked\"><h2>Map a point (u,v) on y=f(x) to the graph of g.</h2><ol class=\"method\"><li>Solve 3(x−1)=u, so x=u/3+1.</li><li>Output becomes 2v+4.</li><li>Point maps to (u/3+1,2v+4).</li></ol><div class=\"formula-panel\">\\[g(x)=2f(3(x-1))+4\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 4","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Map (6,−2) under y=−f(2(x+3))+5.</b></div><textarea class=\"student-note tall\" data-note=\"turn-4\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">x=6/2−3=0 and y=−(−2)+5=7, so (0,7).</div></details></div>","kind":"content","eyebrow":"Order of combined transformations"},{"section":"Concept cycle 4","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“Apply every written operation left to right to the point coordinates.”</p><h3>Repair</h3><p>Relate the transformed input to the original input, then solve for the new coordinate.</p></div></div>","kind":"content","eyebrow":"Order of combined transformations"},{"section":"Concept cycle 5","title":"Inverse functions and reflection","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>An inverse reverses the input-output pairing. The graph of f⁻¹ is the reflection of the graph of f in y=x.</p></article><div class=\"formula-panel\">\\[f(a)=b\\iff f^{-1}(b)=a\\]</div></div>","kind":"content","eyebrow":"5 of 8"},{"section":"Concept cycle 5","title":"Inverse functions and reflection: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"transformations and inverses\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M80 190 Q190 35 300 190 M300 190 Q390 60 475 190\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"55\" y1=\"220\" x2=\"470\" y2=\"35\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">transformations and inverses</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for inverse functions and reflection?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 5","title":"Worked example: Inverse functions and reflection","html":"<div class=\"worked\"><h2>If f passes through (−2,7) and (4,1), state two points on f⁻¹.</h2><ol class=\"method\"><li>Swap each input and output.</li><li>(−2,7) becomes (7,−2).</li><li>(4,1) becomes (1,4).</li></ol><div class=\"formula-panel\">\\[f(a)=b\\iff f^{-1}(b)=a\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 5","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>A function maps 3→11 and 8→−1. State the corresponding inverse mappings.</b></div><textarea class=\"student-note tall\" data-note=\"turn-5\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">11→3 and −1→8.</div></details></div>","kind":"content","eyebrow":"Inverse functions and reflection"},{"section":"Concept cycle 5","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“f⁻¹(x)=1/f(x).”</p><h3>Repair</h3><p>Inverse function reverses the process; reciprocal reverses multiplication.</p></div></div>","kind":"content","eyebrow":"Inverse functions and reflection"},{"section":"Concept cycle 6","title":"Algebraic inverses and units","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>To find an inverse, write y=f(x), swap x and y, and solve. The inverse domain is the original range.</p></article><div class=\"formula-panel\">\\[f(x)=1.8x+32\\]</div></div>","kind":"content","eyebrow":"6 of 8"},{"section":"Concept cycle 6","title":"Algebraic inverses and units: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"transformations and inverses\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M80 190 Q190 35 300 190 M300 190 Q390 60 475 190\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"55\" y1=\"220\" x2=\"470\" y2=\"35\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">transformations and inverses</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for algebraic inverses and units?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 6","title":"Worked example: Algebraic inverses and units","html":"<div class=\"worked\"><h2>Find the inverse of the Celsius-to-Fahrenheit rule.</h2><ol class=\"method\"><li>Write y=1.8x+32.</li><li>Swap: x=1.8y+32.</li><li>Solve y=(x−32)/1.8.</li></ol><div class=\"formula-panel\">\\[f(x)=1.8x+32\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 6","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Find the inverse of f(x)=5x−7.</b></div><textarea class=\"student-note tall\" data-note=\"turn-6\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">f⁻¹(x)=(x+7)/5.</div></details></div>","kind":"content","eyebrow":"Algebraic inverses and units"},{"section":"Concept cycle 6","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“The inverse keeps the same domain automatically.”</p><h3>Repair</h3><p>The domain and range swap; contextual units swap too.</p></div></div>","kind":"content","eyebrow":"Algebraic inverses and units"},{"section":"Concept cycle 7","title":"One-to-one restrictions","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>A function must be one-to-one on its chosen domain to have a function inverse. Restricting a domain can make a non-invertible rule invertible.</p></article><div class=\"formula-panel\">\\[f(x)=x^2,\\quad x\\ge0\\]</div></div>","kind":"content","eyebrow":"7 of 8"},{"section":"Concept cycle 7","title":"One-to-one restrictions: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"transformations and inverses\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M80 190 Q190 35 300 190 M300 190 Q390 60 475 190\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"55\" y1=\"220\" x2=\"470\" y2=\"35\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">transformations and inverses</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for one-to-one restrictions?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 7","title":"Worked example: One-to-one restrictions","html":"<div class=\"worked\"><h2>Find the inverse of f(x)=x² on x≥0.</h2><ol class=\"method\"><li>The restriction makes f one-to-one.</li><li>Swap x=y² with y≥0.</li><li>f⁻¹(x)=√x.</li></ol><div class=\"formula-panel\">\\[f(x)=x^2,\\quad x\\ge0\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 7","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Choose a domain restriction for f(x)=(x−3)²+1 and state the inverse branch.</b></div><textarea class=\"student-note tall\" data-note=\"turn-7\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">For x≥3, f⁻¹(x)=3+√(x−1); for x≤3, use 3−√(x−1).</div></details></div>","kind":"content","eyebrow":"One-to-one restrictions"},{"section":"Concept cycle 7","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“Every function automatically has an inverse function.”</p><h3>Repair</h3><p>It needs one output per input and one input per output on the selected domain.</p></div></div>","kind":"content","eyebrow":"One-to-one restrictions"},{"section":"Concept cycle 8","title":"Composition and inverse checks","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>Composition applies one function to the output of another. It models a sequence of processes; inverse composition should return the identity.</p></article><div class=\"formula-panel\">\\[(f\\circ g)(x)=f(g(x))\\]</div></div>","kind":"content","eyebrow":"8 of 8"},{"section":"Concept cycle 8","title":"Composition and inverse checks: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"transformations and inverses\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M80 190 Q190 35 300 190 M300 190 Q390 60 475 190\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"55\" y1=\"220\" x2=\"470\" y2=\"35\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">transformations and inverses</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for composition and inverse checks?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 8","title":"Worked example: Composition and inverse checks","html":"<div class=\"worked\"><h2>Let f(x)=2x+5 and g(x)=x². Find (f∘g)(3) and (g∘f)(3).</h2><ol class=\"method\"><li>f(g(3))=f(9)=23.</li><li>g(f(3))=g(11)=121.</li><li>Composition is generally not commutative.</li></ol><div class=\"formula-panel\">\\[(f\\circ g)(x)=f(g(x))\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 8","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>For f(x)=3x−4 and f⁻¹(x)=(x+4)/3, simplify f⁻¹(f(x)).</b></div><textarea class=\"student-note tall\" data-note=\"turn-8\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">((3x−4)+4)/3=x.</div></details></div>","kind":"content","eyebrow":"Composition and inverse checks"},{"section":"Concept cycle 8","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“f∘g=g∘f.”</p><h3>Repair</h3><p>Order describes which process happens first and usually changes the result.</p></div></div>","kind":"content","eyebrow":"Composition and inverse checks"},{"section":"Technology laboratory","title":"Interactive laboratory","html":"<div class=\"lab\"><h2>Change a parameter. Predict first. Test second.</h2><p>Use overlays and tables to compare a base graph with its transform; verify inverse graphs by reflection in y=x and by composing rules.</p><div id=\"lesson-lab\" data-lab=\"2.5\"></div></div>","kind":"lab","eyebrow":"Technology with purpose"},{"section":"Technology laboratory","title":"GDC workflow","html":"<div class=\"workflow\"><div><b>1</b><span>Define variables and the valid domain.</span></div><div><b>2</b><span>Enter the model accurately.</span></div><div><b>3</b><span>Choose a window or list that reveals relevant behaviour.</span></div><div><b>4</b><span>Use trace, intersect, regression or solve.</span></div><div><b>5</b><span>Verify and interpret the output.</span></div></div>","kind":"content","eyebrow":"Repeatable process"},{"section":"Technology laboratory","title":"Interpreting calculator output","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Raw output</h2><p>A decimal, regression equation or graph feature is not yet a complete answer.</p></article><article class=\"focus-card\"><h2>IB response</h2><p>State the method, round appropriately, include units, select the contextual solution and explain what it means.</p></article></div>","kind":"content","eyebrow":"Technology → mathematics → context"},{"section":"Technology laboratory","title":"Precision and validation","html":"<div class=\"callout\"><b>Avoid premature rounding.</b> Store or retain full-precision values until the final line. Then test the result in the original model and check whether it belongs to the domain.</div><textarea class=\"student-note\" data-note=\"technology-check\" placeholder=\"Write the validation check you would use for this lesson.\"></textarea>","kind":"content","eyebrow":"Reliable evidence"},{"section":"Case study","title":"Case-study brief","html":"<div class=\"investigation\"><h2>A temperature conversion, a currency conversion and a sensor calibration are all reversible processes. What conditions make reversal possible, and how do graph transformations reveal the structure?</h2><p>Build a model, make at least two assumptions, use technology, and identify evidence that could reject your model.</p></div>","kind":"content","eyebrow":"Mini investigation"},{"section":"Case study","title":"Data and model choice","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Evidence</h2><p>Use numerical, graphical and contextual information. Look for constant differences, ratios, turning points, asymptotes, residual structure or restrictions.</p></article><article class=\"focus-card\"><h2>Choice</h2><p>Select the simplest defensible model. A more complex model requires stronger evidence and clearer parameter interpretation.</p></article></div>","kind":"content","eyebrow":"Model selection"},{"section":"Case study","title":"Decision and interpretation","html":"<div class=\"student-turn\"><h2>Write the decision sentence</h2><p>“According to the model, … because … . This conclusion is valid for … and assumes … .”</p><textarea class=\"student-note tall\" data-note=\"case-decision\" placeholder=\"Complete the sentence for the inquiry context.\"></textarea></div>","kind":"content","eyebrow":"Communicate like an IB student"},{"section":"Case study","title":"Evaluate and extend","html":"<div class=\"reflection-grid\"><div><h2>Validity</h2><p>Does the model reproduce known data and respect physical limits?</p></div><div><h2>Sensitivity</h2><p>How much does the conclusion change when inputs or parameters change?</p></div><div><h2>Extension</h2><p>What additional data or alternative model would strengthen the decision?</p></div></div>","kind":"content","eyebrow":"Reflection is mathematics"},{"section":"Communication","title":"Full-mark response checklist","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"comm-1\"><span>I used the command term at the required depth.</span></label><label><input type=checkbox data-reflect=\"comm-2\"><span>I showed the equation, substitution or technology evidence.</span></label><label><input type=checkbox data-reflect=\"comm-3\"><span>I used correct notation, units and rounding.</span></label><label><input type=checkbox data-reflect=\"comm-4\"><span>I interpreted the result and addressed restrictions.</span></label><label><input type=checkbox data-reflect=\"comm-5\"><span>I evaluated assumptions when the question required judgment.</span></label></div>","kind":"content","eyebrow":"Before submitting"},{"section":"Communication","title":"Theory of Knowledge connection","html":"<div class=\"explain-prompt\"><h2>When does a useful model count as knowledge?</h2><p>Discuss whether predictive accuracy, explanatory mechanism, transparent assumptions and reproducibility contribute differently to trust.</p><textarea class=\"student-note tall\" data-note=\"tok\" placeholder=\"Write a claim, counterclaim and example.\"></textarea></div>","kind":"content","eyebrow":"TOK"},{"section":"Communication","title":"Internal assessment connection","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Possible exploration move</h2><p>Collect or source data, justify a function family, estimate parameters, analyse residuals and discuss limitations.</p></article><article class=\"focus-card\"><h2>Personal engagement</h2><p>Make a mathematical decision in a context you genuinely understand; do not merely reproduce calculator output.</p></article></div>","kind":"content","eyebrow":"IA thinking"},{"section":"Communication","title":"Exam strategy","html":"<div class=\"workflow\"><div><b>Read</b><span>Underline command terms, domain and requested precision.</span></div><div><b>Plan</b><span>Choose algebra, graph, table or regression deliberately.</span></div><div><b>Execute</b><span>Record method and retain full precision.</span></div><div><b>Interpret</b><span>Return to context and units.</span></div><div><b>Check</b><span>Substitute, compare or inspect residuals.</span></div></div>","kind":"content","eyebrow":"Five moves"},{"section":"Closure","title":"Mixed exit ticket","html":"<div class=\"exit-grid\"><div><b>Represent</b><span>Give two representations of one idea from Transformations, Composition, and Inverses.</span></div><div><b>Calculate</b><span>Create and solve a numerical example.</span></div><div><b>Interpret</b><span>Explain a parameter or feature with units.</span></div><div><b>Evaluate</b><span>State one assumption and one limitation.</span></div></div><textarea class=\"student-note tall\" data-note=\"exit\" placeholder=\"Complete all four prompts.\"></textarea>","kind":"content","eyebrow":"Synthesis"},{"section":"Closure","title":"Mastery checklist","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"master-2.5-0\"><span>Describe and construct translations, reflections and stretches of familiar graphs.</span></label><label><input type=checkbox data-reflect=\"master-2.5-1\"><span>Apply more than one transformation in the correct order.</span></label><label><input type=checkbox data-reflect=\"master-2.5-2\"><span>Find and interpret inverse functions and domain restrictions.</span></label><label><input type=checkbox data-reflect=\"master-2.5-3\"><span>Use composition to represent multi-stage processes and verify inverse relationships.</span></label></div>","kind":"content","eyebrow":"Can you do this independently?"},{"section":"Closure","title":"Next route","html":"<div class=\"connection-grid\"><button class=\"primary-btn route-jump\" data-go=\"practice\">Practice Studio · 60 questions</button><button class=\"secondary-btn route-jump\" data-go=\"exam\">IB Tasks · 3 extended responses</button><button class=\"secondary-btn route-jump\" data-go=\"quiz\">Timed Quiz · 12 questions</button><button class=\"secondary-btn route-jump\" data-go=\"review\">Mastery review</button></div>","kind":"content","eyebrow":"Choose evidence"},{"section":"Closure","title":"Lesson complete","html":"<div class=\"launch-panel\"><h2>Transformations, Composition, and Inverses</h2><p>You have completed the Learn route. Use Practice Studio, IB Tasks and the independent quiz to turn familiarity into durable evidence.</p><button class=\"primary-btn route-jump\" data-go=\"review\">Open mastery and mark completion</button></div>","kind":"content","eyebrow":"Bridge to practice"}],"practice":[{"id":"IBAI-2.5-P01","level":"Foundation","prompt":"Describe the transformation from \\(y=f(x)\\) to \\(y=f(x)-6\\).","answer":"Translate 6 units downward.","solution":"Subtracting outside changes every y-value by −6.","marks":2,"calculator":"No GDC required","command":"Describe","hint":"","tags":[],"check":{"mode":"text","accepted":["down 6","translate 6 down","vertical translation -6"]}},{"id":"IBAI-2.5-P02","level":"Foundation","prompt":"Describe the transformation from \\(y=f(x)\\) to \\(y=f(x-4)\\).","answer":"Translate 4 units to the right.","solution":"The horizontal sign is opposite inside the function.","marks":2,"calculator":"No GDC required","command":"Describe","hint":"","tags":[],"check":{"mode":"text","accepted":["right 4","translate 4 right"]}},{"id":"IBAI-2.5-P03","level":"Foundation","prompt":"Describe \\(y=f(x+3)\\).","answer":"Translate 3 units left.","solution":"x+3 means h=−3.","marks":2,"calculator":"No GDC required","command":"Describe","hint":"","tags":[],"check":{"mode":"text","accepted":["left 3","translate 3 left"]}},{"id":"IBAI-2.5-P04","level":"Foundation","prompt":"Reflect every output: describe \\(y=-f(x)\\).","answer":"Reflect in the x-axis.","solution":"All outputs change sign.","marks":2,"calculator":"No GDC required","command":"Describe","hint":"","tags":[],"check":{"mode":"text","accepted":["reflect x-axis","reflection in x-axis"]}},{"id":"IBAI-2.5-P05","level":"Foundation","prompt":"Reflect every input: describe \\(y=f(-x)\\).","answer":"Reflect in the y-axis.","solution":"All input coordinates change sign.","marks":2,"calculator":"No GDC required","command":"Describe","hint":"","tags":[],"check":{"mode":"text","accepted":["reflect y-axis","reflection in y-axis"]}},{"id":"IBAI-2.5-P06","level":"Foundation","prompt":"A point (2,5) lies on y=f(x). Find the corresponding y-coordinate on y=3f(x).","answer":"\\(15\\)","solution":"Vertical stretch multiplies y by 3.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":15.0,"tolerance":0.00015000000000000001}},{"id":"IBAI-2.5-P07","level":"Foundation","prompt":"A point (8,−4) lies on y=f(x). Find its new x-coordinate on y=f(2x).","answer":"\\(4\\)","solution":"Solve 2x=8, so x=4.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":4.0,"tolerance":4e-05}},{"id":"IBAI-2.5-P08","level":"Foundation","prompt":"State the vertex of \\(y=(x+5)^2-2\\).","answer":"\\((-5,-2)\\)","solution":"Vertex form y=(x−h)²+k gives h=−5,k=−2.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["(-5,-2)","−5,−2"]}},{"id":"IBAI-2.5-P09","level":"Foundation","prompt":"If f contains the point (−3,7), state a point on \\(f^{-1}\\).","answer":"\\((7,-3)\\)","solution":"Swap input and output.","marks":2,"calculator":"No GDC required","command":"Write down","hint":"","tags":[],"check":{"mode":"text","accepted":["(7,-3)","7,-3"]}},{"id":"IBAI-2.5-P10","level":"Foundation","prompt":"Find the inverse of \\(f(x)=2x+9\\).","answer":"\\(f^{-1}(x)=\\frac{x-9}{2}\\)","solution":"Swap x and y and solve.","marks":2,"calculator":"No GDC required","command":"Find","hint":"","tags":[],"check":{"mode":"text","accepted":["(x-9)/2","f^-1(x)=(x-9)/2"]}},{"id":"IBAI-2.5-P11","level":"Foundation","prompt":"Find the inverse of \\(g(x)=5-3x\\).","answer":"\\(g^{-1}(x)=\\frac{5-x}{3}\\)","solution":"x=5−3y gives y=(5−x)/3.","marks":2,"calculator":"No GDC required","command":"Find","hint":"","tags":[],"check":{"mode":"text","accepted":["(5-x)/3","g^-1(x)=(5-x)/3"]}},{"id":"IBAI-2.5-P12","level":"Foundation","prompt":"Apply g first and then f, where \\(f(x)=3x-1\\), \\(g(x)=x^2\\), at input 2.","answer":"\\(11\\)","solution":"g(2)=4, then f(4)=11.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":11.0,"tolerance":0.00011}},{"id":"IBAI-2.5-P13","level":"Foundation","prompt":"A two-stage process applies \\(f(x)=3x-1\\) and then squares the result. Find the output for input 2.","answer":"\\(25\\)","solution":"f(2)=5, then g(5)=25.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":25.0,"tolerance":0.00025}},{"id":"IBAI-2.5-P14","level":"Foundation","prompt":"Which restriction makes \\(f(x)=x^2\\) one-to-one?","answer":"x≥0","solution":"On x≥0, each output has one input.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["All real x","x≥0","−3≤x≤3","x≠0"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.5-P15","level":"Foundation","prompt":"For \\(f(x)=4x+7\\), calculate \\(f^{-1}(27)\\).","answer":"\\(5\\)","solution":"Solve 4x+7=27.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":5.0,"tolerance":5e-05}},{"id":"IBAI-2.5-P16","level":"Application","prompt":"Celsius-to-Fahrenheit is \\(F(C)=1.8C+32\\). Find the Celsius value corresponding to 86°F.","answer":"\\(30^\\circ\\text{C}\\)","solution":"Use F⁻¹(F)=(F−32)/1.8.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":30.0,"tolerance":0.00030000000000000003}},{"id":"IBAI-2.5-P17","level":"Application","prompt":"A currency conversion is \\(Q(d)=3.64d-8\\), where d is dollars after a fixed fee. Find d when Q=720.","answer":"\\(200\\)","solution":"Solve 3.64d−8=720.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":200.0,"tolerance":0.002}},{"id":"IBAI-2.5-P18","level":"Application","prompt":"A sensor calibration is \\(S(v)=2.5v+0.4\\). Find the inverse output for S=18.9.","answer":"\\(7.4\\)","solution":"v=(18.9−0.4)/2.5.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":7.4,"tolerance":7.400000000000001e-05}},{"id":"IBAI-2.5-P19","level":"Application","prompt":"A dosage rule maps body mass m to dose D. Interpret the inverse function.","answer":"The inverse gives the body mass that would correspond to a specified dose under the model.","solution":"The units reverse.","marks":3,"calculator":"No GDC required","command":"Interpret","hint":"","tags":[],"check":{"mode":"text","accepted":["mass from dose","body mass corresponding to dose","input mass"]}},{"id":"IBAI-2.5-P20","level":"Application","prompt":"A base cost model is \\(f(x)=12+4x\\). A 15% tax is applied after the base cost. Find the composite total for x=20.","answer":"QAR \\(105.8\\)","solution":"First compute f(20)=92, then multiply by 1.15.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":105.8,"tolerance":0.0010580000000000001}},{"id":"IBAI-2.5-P21","level":"Application","prompt":"A measurement x is first converted by \\(g(x)=x/100\\), then corrected by \\(f(u)=1.03u-0.2\\). Find \\((f\\circ g)(250)\\).","answer":"\\(2.375\\)","solution":"g(250)=2.5, then f(2.5)=2.375.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":2.375,"tolerance":2.375e-05}},{"id":"IBAI-2.5-P22","level":"Application","prompt":"A quadratic graph y=x² has point (3,9). Under \\(y=2f(x-4)+5\\), find the sum of the transformed coordinates.","answer":"\\(30\\)","solution":"The point maps to (7,23); sum=30.","marks":4,"calculator":"No GDC required","command":"Find","hint":"","tags":[],"check":{"mode":"number","value":30.0,"tolerance":0.00030000000000000003}},{"id":"IBAI-2.5-P23","level":"Application","prompt":"The graph of y=f(x) contains (10,−6). Under \\(y=-3f(2x)+4\\), find the transformed y-coordinate.","answer":"\\(22\\)","solution":"y_new=−3(−6)+4=22.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":22.0,"tolerance":0.00022}},{"id":"IBAI-2.5-P24","level":"Application","prompt":"The same point (10,−6) is transformed under \\(y=-3f(2x)+4\\). Find the transformed x-coordinate.","answer":"\\(5\\)","solution":"2x_new=10, so x_new=5.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":5.0,"tolerance":5e-05}},{"id":"IBAI-2.5-P25","level":"Application","prompt":"A quadratic height rule is restricted to the rising part before its maximum. Explain why this helps define an inverse time function.","answer":"On the rising interval each height corresponds to one time, so the restricted function is one-to-one and can be inverted.","solution":"Without the restriction most heights occur twice.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["one-to-one","one height one time","rising branch"]}},{"id":"IBAI-2.5-P26","level":"Application","prompt":"A linear scale \\(L(x)=0.75x+18\\) is followed by \\(M(y)=2y-5\\). Find the overall gradient of \\(M\\circ L\\).","answer":"\\(1.5\\)","solution":"M(L(x))=2(0.75x+18)−5=1.5x+31.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":1.5,"tolerance":1.5000000000000002e-05}},{"id":"IBAI-2.5-P27","level":"Application","prompt":"Find the input that reverses the process “add 8, then multiply by 3” from output 60.","answer":"\\(12\\)","solution":"Reverse in opposite order: divide by 3, then subtract 8: 20−8=12.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":12.0,"tolerance":0.00012000000000000002}},{"id":"IBAI-2.5-P28","level":"Application","prompt":"A conversion function is one-to-one but its inverse gives negative distances for some outputs. State a modelling concern.","answer":"Those outputs may lie outside the original range, so the inverse should be restricted to physically attainable values.","solution":"Algebraic inversion does not remove contextual limits.","marks":3,"calculator":"No GDC required","command":"Comment","hint":"","tags":[],"check":{"mode":"text","accepted":["outputs outside range","invalid output","restrict inverse domain"]}},{"id":"IBAI-2.5-P29","level":"Application","prompt":"For \\(f(x)=2x-3\\) and \\(g(x)=5x+4\\), find \\((f\\circ g)(1)\\).","answer":"\\(15\\)","solution":"g(1)=9; f(9)=15.","marks":2,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":15.0,"tolerance":0.00015000000000000001}},{"id":"IBAI-2.5-P30","level":"Application","prompt":"For the same f and g, find \\((g\\circ f)(1)\\).","answer":"\\(-1\\)","solution":"f(1)=−1; g(−1)=−1.","marks":2,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":-1.0,"tolerance":1e-05}},{"id":"IBAI-2.5-P31","level":"Reasoning","prompt":"Which transformation moves y=f(x) 3 units left?","answer":"f(x+3)","solution":"Horizontal shifts have opposite sign inside.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["f(x−3)","f(x+3)","f(x)−3","3f(x)"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.5-P32","level":"Reasoning","prompt":"Which transformation maps (x,y) to (x/4,−2y)?","answer":"y=−2f(4x)","solution":"Inside 4 compresses x by 4; outside −2 scales and reflects y.","marks":2,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"choices":["y=−2f(4x)","y=−2f(x/4)","y=f(−2x)+4","y=4f(−2x)"],"correct":0,"check":{"mode":"choice","value":0}},{"id":"IBAI-2.5-P33","level":"Reasoning","prompt":"Explain why \\(f(-x)\\) and \\(-f(x)\\) generally produce different graphs.","answer":"f(−x) changes input signs and reflects in the y-axis; −f(x) changes output signs and reflects in the x-axis.","solution":"The operations act on different coordinates.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["input reflection","output reflection","y-axis x-axis"]}},{"id":"IBAI-2.5-P34","level":"Reasoning","prompt":"A function has inverse. Which must be true on its domain?","answer":"It is one-to-one.","solution":"An inverse function requires one input for each output.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"choices":["It is even.","It is one-to-one.","It is quadratic.","Its range is all real numbers."],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.5-P35","level":"Reasoning","prompt":"Explain why \\(f^{-1}(x)\\neq1/f(x)\\) in general.","answer":"The inverse reverses the input-output mapping, whereas 1/f(x) takes the reciprocal of an output at the same input.","solution":"They are distinct operations.","marks":3,"calculator":"No GDC required","command":"Distinguish","hint":"","tags":[],"check":{"mode":"text","accepted":["reverse process not reciprocal","inverse swaps input output","reciprocal different"]}},{"id":"IBAI-2.5-P36","level":"Reasoning","prompt":"If f(4)=−2, which statement is true?","answer":"f⁻¹(−2)=4","solution":"Inverse swaps the ordered pair.","marks":2,"calculator":"No GDC required","command":"Deduce","hint":"","tags":[],"choices":["f⁻¹(4)=−2","f⁻¹(−2)=4","1/f(4)=4","f(−2)=4"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.5-P37","level":"Reasoning","prompt":"Why does the order of composition matter in a multi-stage process?","answer":"The output of the first process becomes the input of the second, so reversing the stages usually changes the result.","solution":"Composition is generally not commutative.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["different operation order","not commutative","first output becomes second input"]}},{"id":"IBAI-2.5-P38","level":"Reasoning","prompt":"Which check verifies that g is the inverse of f?","answer":"f(g(x))=x and g(f(x))=x","solution":"Both compositions should give the identity on appropriate domains.","marks":2,"calculator":"No GDC required","command":"Verify","hint":"","tags":[],"choices":["f(x)=g(x)","f(g(x))=x and g(f(x))=x","f(x)g(x)=1","f(x)+g(x)=0"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.5-P39","level":"Reasoning","prompt":"A graph is reflected in y=x. What happens to domain and range?","answer":"They swap: the inverse domain is the original range and the inverse range is the original domain.","solution":"Coordinates (x,y) become (y,x).","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["swap","domain becomes range","range becomes domain"]}},{"id":"IBAI-2.5-P40","level":"Reasoning","prompt":"A base graph has a vertical asymptote x=2. Under y=f(x−5), the new asymptote is","answer":"x=7","solution":"A shift 5 right moves x=2 to x=7.","marks":2,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"choices":["x=−3","x=2","x=7","y=7"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.5-P41","level":"Reasoning","prompt":"A base graph has horizontal asymptote y=3. Under y=−2f(x)+5, the new asymptote is","answer":"y=−1","solution":"Transform y=3 to y=−2(3)+5=−1.","marks":2,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"choices":["y=−1","y=11","x=−1","y=3"],"correct":0,"check":{"mode":"choice","value":0}},{"id":"IBAI-2.5-P42","level":"Reasoning","prompt":"Explain why y=x² needs a domain restriction before inversion.","answer":"For positive outputs, x and −x give the same value, so the inverse relation would have two outputs.","solution":"Choose one monotonic branch.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["not one-to-one","two inputs same output","±x"]}},{"id":"IBAI-2.5-P43","level":"Reasoning","prompt":"Which point lies on the inverse of a function containing (6,−9)?","answer":"(−9,6)","solution":"Swap coordinates.","marks":2,"calculator":"No GDC required","command":"Write down","hint":"","tags":[],"choices":["(6,9)","(−6,9)","(−9,6)","(9,−6)"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.5-P44","level":"Reasoning","prompt":"A transformed graph appears identical to the original after reflection in the y-axis. What property is suggested?","answer":"The function is even: f(−x)=f(x), so its graph has y-axis symmetry.","solution":"This does not imply invertibility on all real numbers.","marks":3,"calculator":"No GDC required","command":"Deduce","hint":"","tags":[],"check":{"mode":"text","accepted":["even function","f(-x)=f(x)","y-axis symmetry"]}},{"id":"IBAI-2.5-P45","level":"Reasoning","prompt":"Which is a clearly labelled extension rather than necessary core reasoning in this lesson sequence?","answer":"Composition of several functions","solution":"Extended composition is included for enrichment and connected process modelling.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["Reading a translation","Finding an inverse point","Composition of several functions","Stating domain and range"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.5-P46","level":"Challenge","prompt":"Describe the full transformation from \\(y=f(x)\\) to \\(y=-3f(2(x-4))+7\\).","answer":"Compress horizontally by factor 1/2, translate 4 right, reflect in the x-axis, stretch vertically by 3, then translate 7 up.","solution":"Coordinate mapping: (u,v)→(u/2+4,−3v+7).","marks":5,"calculator":"No GDC required","command":"Describe","hint":"","tags":[],"check":{"mode":"text","accepted":["right 4","horizontal compression 1/2","reflect x-axis","vertical stretch 3","up 7"]}},{"id":"IBAI-2.5-P47","level":"Challenge","prompt":"A point (8,−5) lies on f. Under \\(g(x)=4f(3(x+2))-1\\), find the sum of the transformed coordinates.","answer":"\\(-61/3\\approx-20.333\\)","solution":"x=8/3−2=2/3; y=−21; sum=2/3−21=−61/3.","marks":5,"calculator":"GDC permitted","command":"Find","hint":"","tags":[],"check":{"mode":"number","value":-20.333333333333332,"tolerance":0.001}},{"id":"IBAI-2.5-P48","level":"Challenge","prompt":"Find the inverse of \\(f(x)=\\frac{3x-4}{2x+5}\\).","answer":"\\(f^{-1}(x)=\\frac{4+5x}{3-2x}\\)","solution":"Swap x and y, then solve x(2y+5)=3y−4 for y.","marks":5,"calculator":"No GDC required","command":"Find","hint":"","tags":[],"check":{"mode":"text","accepted":["(4+5x)/(3-2x)","f^-1(x)=(4+5x)/(3-2x)"]}},{"id":"IBAI-2.5-P49","level":"Challenge","prompt":"State the domain of the inverse in the previous question.","answer":"\\(x\\ne\\frac32\\)","solution":"The inverse denominator 3−2x cannot be zero; this is the original range restriction.","marks":3,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["x!=3/2","x ≠ 1.5","exclude 3/2"]}},{"id":"IBAI-2.5-P50","level":"Challenge","prompt":"Let \\(f(x)=ax+b\\) and \\(f^{-1}(x)=0.25x-3\\). Find a.","answer":"\\(4\\)","solution":"The inverse slope is 1/a=0.25, so a=4.","marks":4,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":4.0,"tolerance":4e-05}},{"id":"IBAI-2.5-P51","level":"Challenge","prompt":"For \\(f(x)=2x+1\\) and \\(g(x)=x^2-4\\), solve \\((f\\circ g)(x)=11\\) and enter the sum of all real solutions.","answer":"\\(0\\)","solution":"2(x²−4)+1=11 gives 2x²=18, x=±3; sum 0.","marks":5,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":0.0,"tolerance":1e-06}},{"id":"IBAI-2.5-P52","level":"Challenge","prompt":"Find a domain restriction for \\(f(x)=-(x-2)^2+9\\) that gives inverse \\(f^{-1}(x)=2+\\sqrt{9-x}\\).","answer":"Restrict the original function to \\(x\\ge2\\).","solution":"The plus square-root branch returns values at least 2.","marks":4,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"check":{"mode":"text","accepted":["x>=2","[2,infinity)","right branch"]}},{"id":"IBAI-2.5-P53","level":"Challenge","prompt":"A conversion is \\(f(x)=1.2x+15\\). A second process is \\(g(x)=0.8x-6\\). Find the fixed point of \\(g\\circ f\\), where output equals input.","answer":"\\(150\\)","solution":"g(f(x))=0.96x+6; solve x=0.96x+6.","marks":5,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":150.0,"tolerance":0.0015}},{"id":"IBAI-2.5-P54","level":"Challenge","prompt":"Show algebraically that the inverse of \\(f(x)=e^x+4\\) is \\(f^{-1}(x)=\\ln(x-4)\\) and state its domain.","answer":"Swap x=e^y+4, so e^y=x−4 and y=ln(x−4); domain x>4.","solution":"The inverse domain equals the original range.","marks":5,"calculator":"No GDC required","command":"Show that","hint":"","tags":[],"check":{"mode":"text","accepted":["x>4","ln(x-4)","swap and solve"]}},{"id":"IBAI-2.5-P55","level":"Challenge","prompt":"Let \\(f(x)=3x-2\\), \\(g(x)=x+5\\), and \\(h(x)=x^2\\). Find \\((h\\circ f\\circ g)(-1)\\).","answer":"\\(100\\)","solution":"g(−1)=4, f(4)=10, h(10)=100.","marks":4,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":100.0,"tolerance":0.001}},{"id":"IBAI-2.5-P56","level":"Challenge","prompt":"A function maps a time in seconds to distance in metres. State the units of the inverse function.","answer":"The inverse takes distance in metres as input and returns time in seconds.","solution":"The variables and their units swap roles.","marks":3,"calculator":"No GDC required","command":"Interpret","hint":"","tags":[],"check":{"mode":"text","accepted":["seconds from metres","input metres output seconds","s per distance"]}},{"id":"IBAI-2.5-P57","level":"Challenge","prompt":"The graph of f contains (−4,7). Under \\(g(x)=2-f(−x)\\), find the sum of the transformed coordinates.","answer":"\\(-1\\)","solution":"Input reflection sends x to 4; output becomes 2−7=−5; sum=−1.","marks":4,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":-1.0,"tolerance":1e-05}},{"id":"IBAI-2.5-P58","level":"Challenge","prompt":"Explain why a model can be algebraically invertible but contextually non-invertible over a selected range.","answer":"Measurement, rounding or contextual restrictions may cause different real inputs to correspond to the same reported output, so the practical reversal is not unique.","solution":"Mathematical and real-world invertibility can differ.","marks":4,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["rounded outputs","many inputs same observed output","measurement uncertainty","domain restrictions"]}},{"id":"IBAI-2.5-P59","level":"Challenge","prompt":"For \\(f(x)=\\frac{x-1}{x+2}\\), find \\(f(f(4))\\).","answer":"\\(-0.2\\)","solution":"f(4)=3/6=1/2. Then f(1/2)=(−1/2)/(5/2)=−1/5.","marks":5,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":-0.2,"tolerance":1e-06}},{"id":"IBAI-2.5-P60","level":"Challenge","prompt":"A transformed function is \\(g(x)=af(b(x-h))+k\\). List the four parameters and what each controls.","answer":"a controls vertical scale/reflection; b controls reciprocal horizontal scale/reflection; h shifts horizontally; k shifts vertically.","solution":"Signs of a and b introduce reflections.","marks":5,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["a vertical","b horizontal","h horizontal shift","k vertical shift"]}}],"quiz":[{"id":"IBAI-2.5-Q01","level":"Quiz","prompt":"Describe y=f(x)+5.","answer":"Translate 5 units up.","solution":"Outside addition.","marks":2,"calculator":"No GDC required","command":"Describe","hint":"","tags":[],"check":{"mode":"text","accepted":["up 5","translate 5 up"]}},{"id":"IBAI-2.5-Q02","level":"Quiz","prompt":"Describe y=f(x+2).","answer":"Translate 2 units left.","solution":"Inside sign reverses.","marks":2,"calculator":"No GDC required","command":"Describe","hint":"","tags":[],"check":{"mode":"text","accepted":["left 2","translate 2 left"]}},{"id":"IBAI-2.5-Q03","level":"Quiz","prompt":"Which axis reflection changes every output sign in y=−f(x)?","answer":"Reflect in the x-axis.","solution":"Outputs change sign.","marks":2,"calculator":"No GDC required","command":"Describe","hint":"","tags":[],"check":{"mode":"text","accepted":["reflect x-axis","reflection in x-axis"]}},{"id":"IBAI-2.5-Q04","level":"Quiz","prompt":"A point (6,4) is on f. Find its x-coordinate on y=f(3x).","answer":"\\(2\\)","solution":"3x=6.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":2.0,"tolerance":2e-05}},{"id":"IBAI-2.5-Q05","level":"Quiz","prompt":"A point (−2,9) is on f. State the inverse point.","answer":"\\((9,-2)\\)","solution":"Swap coordinates.","marks":2,"calculator":"No GDC required","command":"Write down","hint":"","tags":[],"check":{"mode":"text","accepted":["(9,-2)","9,-2"]}},{"id":"IBAI-2.5-Q06","level":"Quiz","prompt":"Find the inverse of f(x)=4x−7.","answer":"\\((x+7)/4\\)","solution":"Swap and solve.","marks":2,"calculator":"No GDC required","command":"Find","hint":"","tags":[],"check":{"mode":"text","accepted":["(x+7)/4","f^-1(x)=(x+7)/4"]}},{"id":"IBAI-2.5-Q07","level":"Quiz","prompt":"For f(x)=2x+3 and g(x)=x², find (f∘g)(3).","answer":"\\(21\\)","solution":"g(3)=9; f(9)=21.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":21.0,"tolerance":0.00021}},{"id":"IBAI-2.5-Q08","level":"Quiz","prompt":"For the same f and g, find (g∘f)(3).","answer":"\\(81\\)","solution":"f(3)=9; g(9)=81.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":81.0,"tolerance":0.0008100000000000001}},{"id":"IBAI-2.5-Q09","level":"Quiz","prompt":"Which restriction makes y=(x−1)² invertible?","answer":"x≥1","solution":"Choose one monotonic branch.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["All real x","x≥1","−3≤x≤3","x≠1"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.5-Q10","level":"Quiz","prompt":"For f(x)=5x+2, find f⁻¹(42).","answer":"\\(8\\)","solution":"Solve 5x+2=42.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":8.0,"tolerance":8e-05}},{"id":"IBAI-2.5-Q11","level":"Quiz","prompt":"Explain why composition is not usually commutative.","answer":"The first output becomes the second input, so reversing the order usually changes the calculation.","solution":"Give a simple example if needed.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["order matters","different stages","f(g(x)) not g(f(x))"]}},{"id":"IBAI-2.5-Q12","level":"Quiz","prompt":"State how the graph of an inverse is related to the original graph.","answer":"Reflection in \\(y=x\\).","solution":"Coordinates swap.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["reflection y=x","reflect in y=x"]}}],"exam":[{"id":"U2-2.5-T1","style":"Paper 2 · transformations","title":"Transforming a model","calculator":"GDC expected","total_marks":10,"context":"The point (6,−2) lies on y=f(x). Define \\(g(x)=-3f(2(x-4))+5\\).","parts":[{"label":"a","prompt":"Find the corresponding point on g.","marks":4,"answer":"Set 2(x−4)=6, so x=7; y=−3(−2)+5=11. The point is (7,11).","markscheme":"M1 input equation; A1 x; M1 output transform; A1 point."},{"label":"b","prompt":"Describe the transformations from f to g.","marks":4,"answer":"Horizontal compression by factor 1/2, translate 4 right, reflect in the x-axis, stretch vertically by 3, translate 5 up.","markscheme":"One mark per correct transformation/order grouping, maximum 4."},{"label":"c","prompt":"If f has horizontal asymptote y=1, find the horizontal asymptote of g.","marks":2,"answer":"y=−3(1)+5=2.","markscheme":"M1 transform asymptote; A1 result."}]},{"id":"U2-2.5-T2","style":"Paper 2 · inverse","title":"Temperature calibration","calculator":"GDC expected","total_marks":10,"context":"A sensor converts temperature T °C to a signal S by \\(S(T)=1.6T+12\\), for \\(-20\\le T\\le80\\).","parts":[{"label":"a","prompt":"Find S⁻¹(x).","marks":3,"answer":"\\(S^{-1}(x)=\\frac{x-12}{1.6}\\).","markscheme":"M1 swap/solve; A1 formula; A1 notation."},{"label":"b","prompt":"State the domain and range of S⁻¹.","marks":3,"answer":"Domain [−20,140]; range [−20,80].","markscheme":"M1 original output endpoints; A1 inverse domain; A1 inverse range."},{"label":"c","prompt":"Calculate and interpret S⁻¹(100).","marks":2,"answer":"55°C; a signal of 100 corresponds to 55°C.","markscheme":"M1 calculation; A1 interpretation."},{"label":"d","prompt":"Verify one composition identity.","marks":2,"answer":"For example, \\(S^{-1}(S(T))=((1.6T+12)-12)/1.6=T\\).","markscheme":"M1 composition; A1 simplification."}]},{"id":"U2-2.5-T3","style":"Investigation · processes","title":"A multi-stage pricing system","calculator":"GDC expected","total_marks":10,"context":"A base price x is first discounted by 12% using \\(d(x)=0.88x\\), then a delivery charge is added using \\(c(y)=y+18\\), and finally 5% tax is applied using \\(t(z)=1.05z\\).","parts":[{"label":"a","prompt":"Write the composite function P=t∘c∘d.","marks":3,"answer":"\\(P(x)=1.05(0.88x+18)=0.924x+18.9\\).","markscheme":"M1 correct order; M1 substitution; A1 simplified function."},{"label":"b","prompt":"Calculate P(250).","marks":2,"answer":"249.9 QAR.","markscheme":"M1 substitution; A1 value."},{"label":"c","prompt":"Find P⁻¹ and interpret it.","marks":3,"answer":"\\(P^{-1}(p)=\\frac{p-18.9}{0.924}\\); it recovers the original listed price from the final charge.","markscheme":"M1 solve; A1 formula; A1 interpretation."},{"label":"d","prompt":"Explain why reversing the written order without inverse operations would be incorrect.","marks":2,"answer":"Composition is order-dependent; each stage acts on the previous output, and reversing stages changes both the fixed charge and percentage effects.","markscheme":"R1 order; R1 contextual consequence."}]}],"counts":{"slides":64,"practice":60,"quiz":12,"exam":3},"rights":{"student_content":"Original ECHS-authored instructional and assessment content","private_bank_policy":"No source-bank prompt, canonical ID, provenance record or rights record is embedded in public lesson assets."}};
